//! The Unicode 18.0 bidirectional conformance tests, BidiTest.txt and BidiCharacterTest.txt,
//! through the public API. The repository keeps a sample of each (generated by
//! `cargo xtask unicode-gen`); the ignored tests run the whole files from `target/ucd`, as CI
//! does after `cargo xtask unicode-gen --check` downloads them.

use duydas_text::bidi::{Bidi, BidiClass, Direction, bidi_class, visual_order};

/// One character of each class, for BidiTest's class sequences. ON is not a bracket, as
/// BidiTest assumes.
const REPRESENTATIVES: [(&str, char); 23] = [
    ("L", 'a'),
    ("R", '\u{05D0}'),
    ("AL", '\u{0627}'),
    ("EN", '1'),
    ("ES", '+'),
    ("ET", '$'),
    ("AN", '\u{0660}'),
    ("CS", ','),
    ("NSM", '\u{0300}'),
    ("BN", '\u{00AD}'),
    ("B", '\u{2029}'),
    ("S", '\t'),
    ("WS", ' '),
    ("ON", '!'),
    ("LRE", '\u{202A}'),
    ("LRO", '\u{202D}'),
    ("RLE", '\u{202B}'),
    ("RLO", '\u{202E}'),
    ("PDF", '\u{202C}'),
    ("LRI", '\u{2066}'),
    ("RLI", '\u{2067}'),
    ("FSI", '\u{2068}'),
    ("PDI", '\u{2069}'),
];

/// Compares one case: the expected level of each character (None where the test gives x)
/// and the expected display order of the characters with a level.
fn check(
    text: &str,
    direction: Option<Direction>,
    levels: &[Option<u8>],
    order: &[usize],
    paragraph: Option<u8>,
) -> Result<(), String> {
    let bidi = Bidi::new(text, direction);
    let line = bidi.line_levels(0..text.len());
    let actual: Vec<u8> = text.char_indices().map(|(i, _)| line[i]).collect();
    if let Some(expected) = paragraph {
        let found = bidi.paragraphs()[0].level;
        if found != expected {
            return Err(format!("paragraph level {found}, expected {expected}"));
        }
    }
    for (k, (&expected, &found)) in levels.iter().zip(&actual).enumerate() {
        if expected.is_some_and(|e| e != found) {
            return Err(format!("levels {actual:?}, expected {levels:?} (at {k})"));
        }
    }
    let shown: Vec<usize> = visual_order(&actual)
        .into_iter()
        .filter(|&k| levels[k].is_some())
        .collect();
    if shown != order {
        return Err(format!("order {shown:?}, expected {order:?}"));
    }
    Ok(())
}

fn parse_levels(s: &str) -> Vec<Option<u8>> {
    s.split_whitespace()
        .map(|t| (t != "x").then(|| t.parse().expect("a level")))
        .collect()
}

fn parse_order(s: &str) -> Vec<usize> {
    s.split_whitespace()
        .map(|t| t.parse().expect("an index"))
        .collect()
}

/// Runs BidiTest data; returns the number of cases (one per paragraph direction) and the
/// failures.
fn bidi_test(data: &str) -> (usize, Vec<String>) {
    for (name, c) in REPRESENTATIVES {
        assert_eq!(format!("{:?}", bidi_class(c)).to_uppercase(), name, "{c:?}");
    }
    let mut levels = Vec::new();
    let mut order = Vec::new();
    let mut cases = 0;
    let mut failures = Vec::new();
    for line in data
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        if let Some(rest) = line.strip_prefix("@Levels:") {
            levels = parse_levels(rest);
            continue;
        }
        if let Some(rest) = line.strip_prefix("@Reorder:") {
            order = parse_order(rest);
            continue;
        }
        let (classes, bits) = line.split_once(';').expect("classes; bitset");
        let text: String = classes
            .split_whitespace()
            .map(|name| {
                REPRESENTATIVES
                    .iter()
                    .find(|(n, _)| *n == name)
                    .map(|&(_, c)| c)
                    .expect("a class name")
            })
            .collect();
        let bits: u8 = bits.trim().parse().expect("a bitset");
        for (bit, direction) in [
            (1, None),
            (2, Some(Direction::LeftToRight)),
            (4, Some(Direction::RightToLeft)),
        ] {
            if bits & bit == 0 {
                continue;
            }
            cases += 1;
            if let Err(e) = check(&text, direction, &levels, &order, None) {
                failures.push(format!("{classes} ({direction:?}): {e}"));
            }
        }
    }
    (cases, failures)
}

/// Runs BidiCharacterTest data; returns the number of cases and the failures.
fn bidi_character_test(data: &str) -> (usize, Vec<String>) {
    let mut cases = 0;
    let mut failures = Vec::new();
    for line in data
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let fields: Vec<&str> = line.split(';').collect();
        assert_eq!(fields.len(), 5, "{line}");
        let text: String = fields[0]
            .split_whitespace()
            .map(|h| char::from_u32(u32::from_str_radix(h, 16).expect("hex")).expect("a char"))
            .collect();
        let direction = match fields[1].trim() {
            "0" => Some(Direction::LeftToRight),
            "1" => Some(Direction::RightToLeft),
            _ => None,
        };
        let paragraph: u8 = fields[2].trim().parse().expect("a level");
        cases += 1;
        if let Err(e) = check(
            &text,
            direction,
            &parse_levels(fields[3]),
            &parse_order(fields[4]),
            Some(paragraph),
        ) {
            failures.push(format!("{} ({direction:?}): {e}", fields[0]));
        }
    }
    (cases, failures)
}

fn report(name: &str, (cases, failures): (usize, Vec<String>), expected_cases: usize) {
    assert_eq!(cases, expected_cases, "{name}: number of cases");
    assert!(
        failures.is_empty(),
        "{name}: {} of {cases} cases fail:\n{}",
        failures.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn bidi_test_sample() {
    let data = include_str!("data/bidi_test_sample.txt");
    report("BidiTest sample", bidi_test(data), 12_563);
}

#[test]
fn bidi_character_test_sample() {
    let data = include_str!("data/bidi_character_test_sample.txt");
    report("BidiCharacterTest sample", bidi_character_test(data), 2_865);
}

/// The whole file, from the UCD download `cargo xtask unicode-gen` keeps in `target/ucd`.
fn ucd_file(name: &str) -> String {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/ucd/18.0.0")
        .join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run cargo xtask unicode-gen", path.display()))
}

#[test]
#[ignore = "needs the UCD download: cargo xtask unicode-gen"]
fn bidi_test_full() {
    report("BidiTest", bidi_test(&ucd_file("BidiTest.txt")), 770_241);
}

#[test]
#[ignore = "needs the UCD download: cargo xtask unicode-gen"]
fn bidi_character_test_full() {
    report(
        "BidiCharacterTest",
        bidi_character_test(&ucd_file("BidiCharacterTest.txt")),
        91_707,
    );
}

#[test]
fn classes_have_one_name_each() {
    // The generated enum and the test's names agree, so a renamed class fails here first.
    assert_eq!(bidi_class('a'), BidiClass::L);
}
